import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 72 · Christmas recipe: old-fashioned coconut cake, the white Christmas cake (Google Trends 3/11: christmas dessert recipes rising)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, in my grandmother's house, Christmas dinner didn't end with pie. It ended with a tall white cake that looked like it had been out in a snowstorm. Three layers, covered in fluffy white frosting and buried in coconut. Grandma Pearl carried it in on her best glass stand, and every grown-up at that table went quiet.""",
   "tall white coconut layer cake stand", "IT LOOKED LIKE SNOW")
sc("""People tell me their coconut cake comes out dry, or heavy, or the frosting slides right off the sides. So tonight I'm giving you Grandma Pearl's white Christmas coconut cake, step by step, and the five mistakes that ruin it. And stay with me, because the last secret is something Grandma Pearl did the night before, and it's why her cake was the moistest in Richland County.""",
   "dry crumbly cake slice", "WHY YOURS IS DRY")

ch("Grandma Pearl's cake")
sc("""Grandma Pearl grew up on a farm, and when she was a girl, coconut was a luxury. Fresh coconuts came up on the railroad from Florida and the islands, and they only showed up at the grocer's around Christmas. A coconut cake meant you had spent real money, and that you loved the people you were feeding. That's why it became the Christmas cake.""",
   "vintage grocery store coconuts display", "A CHRISTMAS LUXURY")
sc("""She cracked the coconuts herself with a hammer on the back porch. Danny and I got to drink the coconut water out of a jelly glass, and we thought it was the most exotic thing in the world. Then she grated the white meat by hand, and her knuckles bled every Christmas. In a minute I'll tell you why you don't have to do any of that.""",
   "cracking coconut with hammer", "SHE CRACKED THEM HERSELF")
sc("""Coconut cake was a Southern specialty first, honey. In the eighteen hundreds, the cooks of Charleston and Savannah made it for weddings and holidays. When bagged, shredded coconut came to grocery stores at the end of the eighteen hundreds, every home baker in America could make one, and by my mother's time, it was on every church cake table from Georgia to Ohio.""",
   "vintage bag of shredded coconut", "FROM CHARLESTON TO OHIO")

ch("What you need")
sc("""Here's what you need for the cake. Three cups of cake flour, not all-purpose. One tablespoon of baking powder and half a teaspoon of salt. One cup of soft butter. Two cups of sugar. Five egg whites, at room temperature. One cup of canned coconut milk, well stirred. One teaspoon of vanilla, and one teaspoon of coconut extract if you have it.""",
   "cake flour butter sugar eggs coconut milk", "THE INGREDIENTS")
sc("""And here's mistake number one. Using all-purpose flour and whole eggs. All-purpose flour makes a tough, heavy cake. Cake flour makes it soft and tender, like a cloud. And whole eggs turn the cake yellow. Egg whites keep it snow white inside, which is the whole point of a white Christmas cake. Save the yolks for eggnog or custard. Nothing goes to waste.""",
   "separating egg whites bowl", "WHITES ONLY")
sc("""And mistake number two. Using regular milk. Regular milk is fine, but canned coconut milk gives you coconut flavor all the way through the cake, not just on the outside. Grandma Pearl used the coconut water from her fresh coconuts. Coconut milk in a can is the closest thing, and it's about two dollars.""",
   "canned coconut milk pouring", "COCONUT ALL THE WAY THROUGH")

ch("The batter")
sc("""Heat your oven to three hundred fifty. Grease three eight-inch round pans, line the bottoms with a circle of wax paper or parchment, and grease and flour them again. Whisk the flour, baking powder and salt together in one bowl. Now beat the soft butter and sugar together for a full five minutes, until it's pale and fluffy. Don't skip that. That's where the lightness comes from.""",
   "beating butter and sugar mixer", "A FULL FIVE MINUTES")
sc("""Add the egg whites one at a time, beating after each. Add the vanilla and coconut extract. Now add the flour in three parts, alternating with the coconut milk in two parts, starting and ending with flour. Mix on low, only until you can't see any more flour. That's mistake number three, honey. Overmixing makes a tough, rubbery cake.""",
   "folding flour into cake batter", "DON'T OVERMIX")
sc("""If you want to know about the other cakes Grandma Pearl made, tap the like button for me, sweetheart. It helps Grandma more than you know. Divide the batter evenly between the three pans. Grandma Pearl weighed each pan on her kitchen scale, so all three layers came out the same height. Smooth the tops, and tap each pan on the counter twice, to knock out the big air bubbles.""",
   "three cake pans batter on scale", "WEIGH EACH PAN")

sc("""And a word about the oven, honey. Put the three pans on the middle rack, with space between them and the walls, so the heat moves around. If they won't all fit, bake two and keep the third pan in the icebox until there's room. And don't open the oven door for the first eighteen minutes. Every time you peek, the cake can sink right in the middle.""",
   "three cake pans in oven middle rack", "DON'T PEEK")
ch("Baking")
sc("""Bake for twenty-two to twenty-six minutes, until the tops spring back when you touch them, and a toothpick comes out with a few moist crumbs. They should stay pale, honey, not brown. Let them cool in the pans for ten minutes, then turn them out onto a rack, peel off the paper, and let them cool completely.""",
   "white cake layers cooling on rack", "PALE, NOT BROWN")
sc("""And here's mistake number four. Overbaking. Most people leave a cake in until the toothpick comes out completely dry, and by then, the cake is already drying out. A few moist crumbs are perfect. The cake keeps cooking for a few minutes after it comes out of the oven. Set a timer for twenty-two minutes, and check it then.""",
   "toothpick testing cake moist crumbs", "A FEW MOIST CRUMBS")

ch("The secret")
sc("""Now the secret I promised you, the thing Grandma Pearl did the night before. She brushed every layer with a simple syrup, while the cake was still a little warm. Half a cup of sugar and half a cup of coconut milk, heated just until the sugar melts. She brushed it on with a pastry brush, and the cake drank it all up. Then she wrapped each layer in wax paper overnight.""",
   "brushing syrup on cake layer pastry brush", "THE NIGHT BEFORE")
sc("""That's why her cake was the moistest in Richland County. The syrup soaks in, and overnight the crumb gets soft and rich, and it stays that way for days. And a cold, rested cake is so much easier to frost, honey. It doesn't crumble, and it doesn't slide. Bakeries do this, and now you know their secret.""",
   "wrapped cake layers overnight", "THE BAKERY SECRET")

ch("The frosting")
sc("""Grandma Pearl used a seven-minute frosting, but I'll give you the easy one I've used for forty years. Beat eight ounces of soft cream cheese with half a cup of soft butter until smooth. Add four cups of powdered sugar, a pinch of salt, a teaspoon of vanilla, and half a teaspoon of coconut extract. Beat until fluffy and white.""",
   "cream cheese frosting whipped bowl", "FLUFFY AND WHITE")
sc("""Put the first layer on your cake stand, and spread a thick layer of frosting on top. Sprinkle on a big handful of coconut. Repeat with the second layer, then the third. Now frost the top and sides with a thin coat first, to catch the crumbs, and chill it for twenty minutes. Then put on the second, thick coat. That's the crumb coat trick, and it keeps the white frosting perfectly white.""",
   "frosting layer cake crumb coat", "THE CRUMB COAT")
sc("""Now mistake number five. Not using enough coconut. You need about three cups of sweetened flaked coconut. Hold the cake stand in one hand, and press the coconut onto the sides with the other, a handful at a time. Then pile the rest on top. It should look like a snowdrift, sweetheart. For a little color, put a ring of red cherries or fresh cranberries on top.""",
   "pressing coconut onto cake sides", "LIKE A SNOWDRIFT")

sc("""And if you'd like to try it Grandma Pearl's way, with fresh coconut, here's how. Poke out two of the eyes with a screwdriver, drain the water, and bake the whole coconut at three fifty for fifteen minutes. The shell cracks easily, and the meat pulls right away. Then grate it on the small holes of a box grater. It's moister and less sweet than the bag, and it smells like heaven.""",
   "fresh grated coconut box grater", "GRANDMA PEARL'S WAY")
ch("Serving it")
sc("""Keep it covered in the icebox, honey, and take it out an hour before dinner, so the frosting softens. Cut it with a long knife dipped in hot water and wiped dry between every slice. It keeps for five days, and it's better on day two. Grandma Pearl always said the cake was a little sweeter on the twenty-sixth, once all the company had gone home.""",
   "slice of coconut layer cake plate", "BETTER ON DAY TWO")
sc("""The last Christmas Grandma Pearl was with us, in nineteen seventy-four, her hands were too shaky to frost, so I did it for her. She sat at the kitchen table and told me exactly what to do, every step. When I carried it in, she said, that's my cake, Ruthie. Now it's yours. I've made it every Christmas since.""",
   "elderly grandmother kitchen table granddaughter", "NOW IT'S YOURS")

ch("Grandma's kitchen")
sc("""So one more time. Cake flour and egg whites only, for a soft, snow-white cake. Coconut milk in the batter. Don't overmix, and don't overbake. Brush the layers with coconut syrup the night before. A crumb coat, then the thick coat. And pile on three cups of coconut, like a snowdrift. That's a Christmas cake your family will ask for every year.""",
   "white Christmas coconut cake table", "A CAKE THEY'LL ASK FOR")
sc("""Tell me in the comments, sweetheart. What was the special Christmas dessert in your family? I'd love to hear about it. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey. Merry Christmas.""",
   "Christmas dessert table candles", "YOUR CHRISTMAS DESSERT?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma72", "Coconut Cake EVERYONE's Grandma Made at Christmas (Why Yours Is DRY)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Coconut layer cake, a Southern holiday cake of the 19th century, popularized nationally by packaged shredded coconut in the late 1800s.",
      "Recipe as written by Grandma Ruth: 3 cups cake flour, 1 tbsp baking powder, 1/2 tsp salt, 1 cup butter, 2 cups sugar, 5 egg whites, 1 cup coconut milk, vanilla and coconut extract; 3 eight-inch pans at 350F for 22-26 minutes; coconut syrup; cream cheese frosting; 3 cups flaked coconut."],
     "christmas recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
